import 'package:drift/drift.dart'; import '../app_database.dart';
@DriftAccessor()
class NotificationDao extends DatabaseAccessor<AppDatabase> { NotificationDao(AppDatabase db):super(db); Future<List<AppNotification>> getNotificationsForUser(String id)=>(db.select(db.appNotifications)..where((t)=>t.recipientId.equals(id))..orderBy([(t)=>OrderingTerm.desc(t.createdAt)])).get(); Future<List<AppNotification>> getUnreadNotificationsForUser(String id)=>(db.select(db.appNotifications)..where((t)=>t.recipientId.equals(id)&t.isRead.equals(false))).get(); Future<int> getUnreadCount(String id) async { final c=db.appNotifications.id.count(); return (await (db.selectOnly(db.appNotifications)..addColumns([c])..where(db.appNotifications.recipientId.equals(id)&db.appNotifications.isRead.equals(false))).getSingle()).read(c)??0; } Future<void> insertNotification(AppNotificationsCompanion v)=>db.into(db.appNotifications).insert(v); Future<int> markAsRead(String id,DateTime at)=>(db.update(db.appNotifications)..where((t)=>t.id.equals(id))).write(AppNotificationsCompanion(isRead:const Value(true),readAt:Value(at.toUtc()))); Future<int> markAllAsRead(String user,DateTime at)=>(db.update(db.appNotifications)..where((t)=>t.recipientId.equals(user)&t.isRead.equals(false))).write(AppNotificationsCompanion(isRead:const Value(true),readAt:Value(at.toUtc()))); }
